argv:
$ErrorActionPreference='SilentlyContinue';
$urls=@(
  'http://127.0.0.1:17448/api/status',
  'http://127.0.0.1:17448/api/operator-lifecycle',
  'http://127.0.0.1:17448/api/projects/control-plane?inspect=0',
  'http://127.0.0.1:17448/api/projects/control-plane/cutover-r42/status'
);
$out=@();
foreach($u in $urls){
  try{
    $r=Invoke-RestMethod -Uri $u -TimeoutSec 4;
    $out += [pscustomobject]@{url=$u;ok=$true;body=$r}
  }catch{
    $out += [pscustomobject]@{url=$u;ok=$false;error=$_.Exception.Message}
  }
}
$git=[pscustomobject]@{path='E:\WebAIBridge';head='';branch='';status=@()};
if(Test-Path 'E:\WebAIBridge\.git'){
  Push-Location 'E:\WebAIBridge';
  $git.head=(git rev-parse HEAD 2>$null).Trim();
  $git.branch=(git branch --show-current 2>$null).Trim();
  $git.status=@(git status --short);
  Pop-Location;
}
[pscustomobject]@{git=$git;endpoints=$out}|ConvertTo-Json -Depth 12 -Compress
